  grammar: [
    {"pat": "V thể て ＋ しまいました", "desc": "Diễn tả sự tiếc nuối, đáng tiếc vì đã lỡ làm (hoặc lỡ xảy ra) một việc ngoài ý muốn: “lỡ ~ mất rồi”.\nCách chia: V thể て ＋ しまいました\n• 忘（わす）れます → 忘れて → 忘れてしまいました\n• 落（お）とします → 落として → 落としてしまいました\n• 飲（の）みます → 飲んで → 飲んでしまいました\nVăn nói thân mật: ～てしまった → ～ちゃった, ～でしまった → ～じゃった.\nLưu ý: ～てしまいました còn có nghĩa “làm xong hết” (宿題（しゅくだい）を全部（ぜんぶ）やってしまいました), nhưng ở bài này chủ yếu là nghĩa hối tiếc.", "ex": [{"jp": "電車（でんしゃ）に傘（かさ）を忘（わす）れてしまいました。", "ro": "Densha ni kasa o wasurete shimaimashita.", "vi": "Tôi lỡ để quên ô trên tàu điện mất rồi."}]},
    {"pat": "Thể thường ＋ かもしれません", "desc": "Diễn tả sự phỏng đoán chưa chắc chắn: “có lẽ ~, có thể ~”. Mức độ chắc chắn thấp hơn ～でしょう.\nCách chia: V／イA thể thường ＋ かもしれません; ナA và N bỏ だ.\n• 間（ま）に合（あ）わない → 間に合わないかもしれません\n• 寒（さむ）い → 寒いかもしれません\n• 大変（たいへん）だ → 大変かもしれません\n• 雨（あめ）だ → 雨かもしれません\nThân mật: ～かもしれない／～かも.", "ex": [{"jp": "約束（やくそく）の時間（じかん）に間（ま）に合（あ）わないかもしれません。", "ro": "Yakusoku no jikan ni maniawanai kamo shiremasen.", "vi": "Có lẽ tôi sẽ không kịp giờ hẹn."}, {"jp": "明日（あした）は雨（あめ）かもしれません。", "ro": "Ashita wa ame kamo shiremasen.", "vi": "Ngày mai có thể trời sẽ mưa."}]},
    {"pat": "Nの／V thể た ＋ あとで、～", "desc": "Diễn tả thứ tự thời gian: “sau khi A thì B”.\n• N ＋ の ＋ あとで: 授業（じゅぎょう） → 授業のあとで\n• V thể た ＋ あとで: 飲（の）みます → 飲んだ → 飲んだあとで\nLưu ý: động từ trước あとで luôn ở thể た, kể cả khi vế sau là việc trong tương lai.\nPhân biệt: Vてから nhấn mạnh “làm A xong rồi mới B” (liền mạch); あとで chỉ đơn thuần nêu B xảy ra sau A.", "ex": [{"jp": "授業（じゅぎょう）のあとで、友達（ともだち）と食事（しょくじ）します。", "ro": "Jugyou no ato de, tomodachi to shokuji shimasu.", "vi": "Sau giờ học, tôi sẽ đi ăn với bạn."}, {"jp": "喫茶店（きっさてん）でコーヒーを飲（の）んだあとで、映画（えいが）を見（み）に行（い）きました。", "ro": "Kissaten de koohii o nonda ato de, eiga o mi ni ikimashita.", "vi": "Sau khi uống cà phê ở quán, tôi đã đi xem phim."}]},
    {"pat": "V thể て ＋ いただけませんか", "desc": "Cách nhờ vả rất lịch sự: “anh/chị có thể ~ giúp tôi được không ạ?”. Dùng với người trên, người lạ, nhân viên…\nCách chia: V thể て ＋ いただけませんか\n• 預（あず）かります → 預かって → 預かっていただけませんか\n• 教（おし）えます → 教えて → 教えていただけませんか\nMức độ lịch sự tăng dần: ～てください → ～てくれませんか → ～てもらえませんか → ～ていただけませんか.", "ex": [{"jp": "すみません、荷物（にもつ）を預（あず）かっていただけませんか。", "ro": "Sumimasen, nimotsu o azukatte itadakemasen ka.", "vi": "Xin lỗi, anh/chị có thể giữ hộ tôi hành lý được không ạ?"}]},
    {"pat": "～て／～くて／～で／～なくて、～（nguyên nhân）", "desc": "Thể て nối hai vế, vế trước là nguyên nhân, vế sau là kết quả: “vì ~ nên ~”.\n• イA: 速（はや）い → 速くて\n• イA phủ định: よくない → よくなくて\n• ナA: 複雑（ふくざつ）だ → 複雑で\n• ナA phủ định: 複雑じゃない → 複雑じゃなくて\n• V: 飲（の）みすぎます → 飲みすぎて\n• V phủ định: わからない → わからなくて\nLưu ý: vế sau thường là cảm xúc, trạng thái hoặc khả năng (困（こま）りました、よかったです、聞（き）き取（と）れません…). Không dùng khi vế sau là mệnh lệnh, nhờ vả, rủ rê, ý chí — khi đó dùng から／ので.", "ex": [{"jp": "アナウンスが速（はや）くて、聞（き）き取（と）れません。", "ro": "Anaunsu ga hayakute, kikitoremasen.", "vi": "Thông báo nói nhanh quá nên tôi không nghe rõ được."}, {"jp": "天気（てんき）がよくなくて、富士山（ふじさん）が見（み）えませんでした。", "ro": "Tenki ga yokunakute, Fujisan ga miemasen deshita.", "vi": "Vì thời tiết không đẹp nên đã không nhìn thấy núi Phú Sĩ."}, {"jp": "地図（ちず）が複雑（ふくざつ）で、わかりません。", "ro": "Chizu ga fukuzatsu de, wakarimasen.", "vi": "Bản đồ phức tạp quá nên tôi không hiểu."}, {"jp": "乗（の）り換（か）えが複雑（ふくざつ）じゃなくて、よかったです。", "ro": "Norikae ga fukuzatsu ja nakute, yokatta desu.", "vi": "May mà việc đổi tàu không phức tạp."}, {"jp": "お酒（さけ）を飲（の）みすぎて、気持（きも）ちが悪（わる）くなりました。", "ro": "O-sake o nomisugite, kimochi ga waruku narimashita.", "vi": "Vì uống rượu quá nhiều nên tôi thấy khó chịu trong người."}, {"jp": "駅（えき）への行（い）き方（かた）がわからなくて、困（こま）りました。", "ro": "Eki e no ikikata ga wakaranakute, komarimashita.", "vi": "Vì không biết đường đến ga nên tôi đã rất lúng túng."}]},
    {"pat": "V thể た ＋ ら、～た（phát hiện）", "desc": "Diễn tả việc sau khi làm hành động A thì phát hiện, nhận ra sự việc B (thường bất ngờ): “làm A thì (hóa ra) B”.\nCách chia: V thể た ＋ ら, vế sau ở thì quá khứ.\n• 開（あ）けます → 開けた → 開けたら\n• 着（つ）きます → 着いた → 着いたら\nLưu ý: vế B là sự việc người nói nhận thấy, không phải hành động có chủ ý của người nói. Khác với ～たら điều kiện “nếu ~ thì ~” (vế sau thường ở tương lai).", "ex": [{"jp": "かばんを開（あ）けたら、財布（さいふ）がありませんでした。", "ro": "Kaban o aketara, saifu ga arimasen deshita.", "vi": "Mở túi ra thì không thấy ví đâu cả."}]},
    {"pat": "Tóm tắt", "desc": "• V thể て ＋ しまいました → lỡ làm ~ mất rồi (tiếc nuối)\n• Thể thường ＋ かもしれません → có lẽ ~ (ナA・N bỏ だ)\n• Nの／V thể た ＋ あとで → sau khi ~\n• V thể て ＋ いただけませんか → nhờ rất lịch sự: có thể ~ giúp tôi không ạ\n• ～くて／～で／～なくて／Vて、～ → vì ~ nên ~ (nguyên nhân)\n• V thể た ＋ ら、～た → làm ~ thì phát hiện ra ~", "ex": []}
  ],

